package com.gathin.tvhome;
import android.content.*;import android.content.pm.*;import java.io.*;import org.json.*;import java.util.*;
final class WebApps{
 static boolean protectedApp(Context c,PackageInfo p){return p.packageName.equals(c.getPackageName())||p.packageName.equals("com.alibaba.dingtalk.focus")||(p.applicationInfo.flags&ApplicationInfo.FLAG_SYSTEM)!=0||p.packageName.contains("settings");}
 static JSONArray list(Context c)throws Exception{PackageManager pm=c.getPackageManager();List<JSONObject> all=new ArrayList<>();for(PackageInfo p:pm.getInstalledPackages(0)){Intent launch=pm.getLeanbackLaunchIntentForPackage(p.packageName);if(launch==null)launch=pm.getLaunchIntentForPackage(p.packageName);all.add(new JSONObject().put("package",p.packageName).put("label",p.applicationInfo.loadLabel(pm)).put("version",p.versionName==null?"":p.versionName).put("launchable",launch!=null).put("removable",!protectedApp(c,p)));}all.sort((a,b)->a.optString("label").compareToIgnoreCase(b.optString("label")));return new JSONArray(all);}
 static String valid(Context c,String pkg)throws Exception{if(!pkg.matches("[A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+"))throw new IllegalArgumentException("应用包名无效");c.getPackageManager().getPackageInfo(pkg,0);return pkg;}
 static void launch(Context c,String pkg)throws Exception{valid(c,pkg);PackageManager pm=c.getPackageManager();Intent i=pm.getLeanbackLaunchIntentForPackage(pkg);if(i==null)i=pm.getLaunchIntentForPackage(pkg);if(i==null)throw new IllegalArgumentException("此应用没有可打开的界面");c.startActivity(i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 static void uninstall(Context c,String pkg,boolean confirm)throws Exception{valid(c,pkg);if(!confirm)throw new IllegalArgumentException("请先确认卸载");if(protectedApp(c,c.getPackageManager().getPackageInfo(pkg,0)))throw new IllegalArgumentException("系统组件、设置和桌面受到保护，不能从网页卸载");String result=TvAdb.shell(c,"pm uninstall "+pkg);if(!result.contains("Success"))throw new IOException("卸载失败："+result);}
 static File staging(Context c){File d=new File(c.getExternalFilesDir(null),"web-apk");d.mkdirs();return d;}
 static void install(Context c,File apk)throws Exception{PackageInfo info=c.getPackageManager().getPackageArchiveInfo(apk.getPath(),0);if(info==null)throw new IOException("安装包无法读取");if(info.packageName.equals(c.getPackageName())||info.packageName.equals("com.alibaba.dingtalk.focus"))throw new IOException("桌面及主页入口请通过维护更新，不能从此处替换");File helper=new File(staging(c),"session.jar");try(InputStream in=c.getAssets().open("session.jar");OutputStream out=new FileOutputStream(helper)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}String output=TvAdb.shell(c,"CLASSPATH="+helper.getPath()+" app_process /system/bin CreateSession");java.util.regex.Matcher matcher=java.util.regex.Pattern.compile("(?m)^\\s*(\\d+)\\s*$").matcher(output);if(!matcher.find())throw new IOException("无法创建安装会话："+output);String id=matcher.group(1);boolean done=false;try{String result=TvAdb.shell(c,"cat "+apk.getPath()+" | pm install-write -S "+apk.length()+" "+id+" base.apk -");if(!result.contains("Success"))throw new IOException(result);result=TvAdb.shell(c,"pm install-commit "+id);if(!result.contains("Success"))throw new IOException(result);done=true;}finally{if(!done)try{TvAdb.shell(c,"pm install-abandon "+id);}catch(Exception ignored){}}}
}
